#!/usr/bin/env node
/**
 * Acquisition driver for the LEGACY-NEXT candidate codyogden/killedbygoogle.
 *
 * Working tool, not evidence. Every accepted response is appended to a probe
 * ledger; the evidence records are written by the sibling drivers from the
 * ledger and from the extracted tree, never from this script's assumptions.
 *
 * Network policy: acquisition only, GET only, no credentials, no redirects,
 * no retries, no alternate hosts, hard byte caps, archive fetched twice and
 * required to be byte-identical.
 */
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync, appendFileSync, existsSync } from 'node:fs';
import { request } from 'node:https';
import { dirname, join } from 'node:path';

const REPO = 'codyogden/killedbygoogle';
const COMMIT = '56809c31592e6ca1edce8af9bfe842fbcdf71f4d';
const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';

const EVIDENCE_ROOT = 'evidence/ingests/next-killedbygoogle-v3-0-0';
const CACHE_ROOT = '.versionless/cache/next-killedbygoogle-v3-0-0-source';

const CAPS = {
  maximumAcceptedResponses: 8,
  maximumApiResponseBytes: 16777216,
  maximumArchiveBytes: 134217728,
  maximumAggregateWireBytes: 314572800,
};

if (process.env.VERSIONLESS_NETWORK_MODE !== 'consented') {
  console.error('refused: VERSIONLESS_NETWORK_MODE is not "consented"');
  process.exit(2);
}
if (process.env.VERSIONLESS_CONSENT_ID !== CONSENT) {
  console.error('refused: consent id mismatch');
  process.exit(2);
}

const ALLOWED_HOSTS = new Set(['api.github.com', 'codeload.github.com']);
let accepted = 0;
let aggregateBytes = 0;
const ledgerPath = join(EVIDENCE_ROOT, 'probe-ledger.ndjson');
mkdirSync(dirname(ledgerPath), { recursive: true });
mkdirSync(join(CACHE_ROOT, 'archive'), { recursive: true });
mkdirSync(join(CACHE_ROOT, 'api'), { recursive: true });

function ledger(entry) {
  appendFileSync(ledgerPath, JSON.stringify(entry) + '\n');
}

function get(url, { maxBytes, label, stream }) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    if (u.protocol !== 'https:') return reject(new Error('non-https url refused'));
    if (!ALLOWED_HOSTS.has(u.hostname)) return reject(new Error(`host not allowed: ${u.hostname}`));
    if (accepted >= CAPS.maximumAcceptedResponses) return reject(new Error('response cap reached'));

    const startedAt = new Date().toISOString();
    const req = request(
      {
        hostname: u.hostname,
        path: u.pathname + u.search,
        method: 'GET',
        headers: {
          accept: label === 'archive' ? 'application/octet-stream' : 'application/vnd.github+json',
          'user-agent': 'versionless-legacy-corpus-ingest',
          'accept-encoding': 'identity',
        },
      },
      (res) => {
        const chunks = [];
        let bytes = 0;
        if (res.statusCode !== 200) {
          res.resume();
          ledger({
            at: startedAt,
            label,
            url,
            status: res.statusCode,
            accepted: false,
            reason: 'non-200 status; no redirect and no retry is permitted',
          });
          return reject(new Error(`status ${res.statusCode} for ${url}`));
        }
        res.on('data', (c) => {
          bytes += c.length;
          if (bytes > maxBytes) {
            req.destroy();
            return reject(new Error(`byte cap exceeded for ${url}`));
          }
          chunks.push(c);
        });
        res.on('end', () => {
          const body = Buffer.concat(chunks);
          const sha256 = createHash('sha256').update(body).digest('hex');
          accepted += 1;
          aggregateBytes += body.length;
          if (aggregateBytes > CAPS.maximumAggregateWireBytes) {
            return reject(new Error('aggregate byte cap exceeded'));
          }
          ledger({
            at: startedAt,
            completedAt: new Date().toISOString(),
            label,
            stream: stream ?? null,
            url,
            method: 'GET',
            status: 200,
            accepted: true,
            bytes: body.length,
            sha256,
            contentEncoding: res.headers['content-encoding'] ?? 'identity',
            redirected: false,
            credentialsSent: false,
            setCookieCount: Array.isArray(res.headers['set-cookie'])
              ? res.headers['set-cookie'].length
              : 0,
          });
          resolve({ body, sha256, bytes: body.length });
        });
      },
    );
    req.on('error', reject);
    req.end();
  });
}

const out = {};

// 1. repository metadata
{
  const url = `https://api.github.com/repos/${REPO}`;
  const r = await get(url, { maxBytes: CAPS.maximumApiResponseBytes, label: 'repository' });
  writeFileSync(join(CACHE_ROOT, 'api', 'repository.json'), r.body);
  out.repository = { url, bytes: r.bytes, sha256: r.sha256, json: JSON.parse(r.body.toString('utf8')) };
}

// 2. the pinned commit object
{
  const url = `https://api.github.com/repos/${REPO}/git/commits/${COMMIT}`;
  const r = await get(url, { maxBytes: CAPS.maximumApiResponseBytes, label: 'commit' });
  writeFileSync(join(CACHE_ROOT, 'api', 'commit.json'), r.body);
  const json = JSON.parse(r.body.toString('utf8'));
  if (json.sha !== COMMIT) throw new Error('commit sha mismatch from wire');
  out.commit = { url, bytes: r.bytes, sha256: r.sha256, json };
}

// 3. the recursive tree at the pinned commit
{
  const treeSha = out.commit.json.tree.sha;
  const url = `https://api.github.com/repos/${REPO}/git/trees/${treeSha}?recursive=1`;
  const r = await get(url, { maxBytes: CAPS.maximumApiResponseBytes, label: 'tree' });
  writeFileSync(join(CACHE_ROOT, 'api', 'tree.json'), r.body);
  out.tree = { url, bytes: r.bytes, sha256: r.sha256, json: JSON.parse(r.body.toString('utf8')) };
}

// 4 + 5. the archive, twice, required byte-identical
const archiveUrl = `https://codeload.github.com/${REPO}/tar.gz/${COMMIT}`;
for (const stream of [1, 2]) {
  const dest = join(CACHE_ROOT, 'archive', `archive-${stream}.tar.gz`);
  if (existsSync(dest)) continue;
  const r = await get(archiveUrl, { maxBytes: CAPS.maximumArchiveBytes, label: 'archive', stream });
  writeFileSync(dest, r.body);
  out[`archive${stream}`] = { url: archiveUrl, bytes: r.bytes, sha256: r.sha256 };
}

const identical =
  out.archive1 && out.archive2
    ? out.archive1.sha256 === out.archive2.sha256 && out.archive1.bytes === out.archive2.bytes
    : null;

writeFileSync(
  join(CACHE_ROOT, 'acquisition-summary.json'),
  JSON.stringify(
    {
      repository: REPO,
      commit: COMMIT,
      acceptedResponses: accepted,
      aggregateWireBytes: aggregateBytes,
      archivesByteIdentical: identical,
      repositoryResponse: { bytes: out.repository.bytes, sha256: out.repository.sha256 },
      commitResponse: { bytes: out.commit.bytes, sha256: out.commit.sha256 },
      treeResponse: { bytes: out.tree.bytes, sha256: out.tree.sha256 },
      archive: out.archive1 ?? null,
      archiveSecondStream: out.archive2 ?? null,
    },
    null,
    2,
  ) + '\n',
);

console.log(
  JSON.stringify(
    {
      accepted,
      aggregateBytes,
      archivesByteIdentical: identical,
      commitDate: out.commit.json.committer?.date,
      treeSha: out.commit.json.tree.sha,
      treeTruncated: out.tree.json.truncated,
      treeEntries: out.tree.json.tree.length,
      archived: out.repository.json.archived,
      license: out.repository.json.license?.spdx_id,
    },
    null,
    2,
  ),
);

