#!/usr/bin/env node
/**
 * Offline reconciliation driver. Extracts the acquired archive under a safety
 * pre-scan and compares every regular file against the recursive git tree at
 * blob level. Writes a machine reconciliation record plus the facts the
 * admission gates need (licence bytes, manifest, lock state, LFS, journeys).
 * No network.
 */
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync, readdirSync, statSync, lstatSync } from 'node:fs';
import { join, relative } from 'node:path';

const CACHE_ROOT = '.versionless/cache/next-killedbygoogle-v3-0-0-source';
const EVIDENCE_ROOT = 'evidence/ingests/next-killedbygoogle-v3-0-0';
const ARCHIVE = join(CACHE_ROOT, 'archive', 'archive-1.tar.gz');
const EXTRACT = join(CACHE_ROOT, 'verify', 'extracted');

const tree = JSON.parse(readFileSync(join(CACHE_ROOT, 'api', 'tree.json'), 'utf8'));

// --- safety pre-scan of archive entry names -------------------------------
const listing = execFileSync('tar', ['-tzf', ARCHIVE], { encoding: 'utf8', maxBuffer: 1 << 28 })
  .split('\n')
  .filter(Boolean);
const roots = new Set(listing.map((p) => p.split('/')[0]));
const traversal = listing.filter((p) => p.split('/').includes('..'));
const absolute = listing.filter((p) => p.startsWith('/'));
if (roots.size !== 1) throw new Error(`archive is not single-rooted: ${[...roots].join(', ')}`);
if (traversal.length || absolute.length) throw new Error('unsafe archive entry names');
const archiveRoot = [...roots][0];

mkdirSync(EXTRACT, { recursive: true });
execFileSync('tar', ['-xzf', ARCHIVE, '-C', EXTRACT]);
const srcRoot = join(EXTRACT, archiveRoot);

// --- walk the extracted tree ---------------------------------------------
function walk(dir, acc = []) {
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name);
    const st = lstatSync(abs);
    if (st.isDirectory()) {
      acc.push({ kind: 'dir', path: relative(srcRoot, abs) });
      walk(abs, acc);
    } else if (st.isSymbolicLink()) {
      acc.push({ kind: 'symlink', path: relative(srcRoot, abs) });
    } else if (st.isFile()) {
      acc.push({ kind: 'file', path: relative(srcRoot, abs), bytes: st.size });
    } else {
      acc.push({ kind: 'special', path: relative(srcRoot, abs) });
    }
  }
  return acc;
}
const entries = walk(srcRoot);

function gitBlobSha(buf) {
  return createHash('sha1').update(`blob ${buf.length}\0`).update(buf).digest('hex');
}

const treeBlobs = new Map(tree.tree.filter((e) => e.type === 'blob').map((e) => [e.path, e]));
const treeDirs = tree.tree.filter((e) => e.type === 'tree');
const treeCommits = tree.tree.filter((e) => e.type === 'commit');
const treeSymlinks = tree.tree.filter((e) => e.mode === '120000');
const treeExecutable = tree.tree.filter((e) => e.mode === '100755');

const files = entries.filter((e) => e.kind === 'file');
const mismatched = [];
const extra = [];
const blobShaByPath = new Map();
const sha256ByPath = new Map();
for (const f of files) {
  const buf = readFileSync(join(srcRoot, f.path));
  const sha = gitBlobSha(buf);
  blobShaByPath.set(f.path, sha);
  sha256ByPath.set(f.path, createHash('sha256').update(buf).digest('hex'));
  const t = treeBlobs.get(f.path);
  if (!t) extra.push(f.path);
  else if (t.sha !== sha) mismatched.push({ path: f.path, tree: t.sha, archive: sha });
}
const missing = [...treeBlobs.keys()].filter((p) => !blobShaByPath.has(p));

// normalized manifest: sorted path\0blobsha lines
const manifest = [...blobShaByPath.entries()]
  .sort(([a], [b]) => (a < b ? -1 : 1))
  .map(([p, s]) => `${s}  ${p}`)
  .join('\n');
const normalizedManifestSha256 = createHash('sha256').update(manifest + '\n').digest('hex');

// --- LFS check ------------------------------------------------------------
const lfsPointers = files.filter((f) => {
  if (f.bytes > 1024) return false;
  const head = readFileSync(join(srcRoot, f.path)).subarray(0, 60).toString('utf8');
  return head.startsWith('version https://git-lfs.github.com/spec/');
});

const readText = (p) => readFileSync(join(srcRoot, p), 'utf8');
const pkg = JSON.parse(readText('package.json'));
const licenseBuf = readFileSync(join(srcRoot, 'LICENSE'));
const licenseText = licenseBuf.toString('utf8');

const record = {
  archiveRoot,
  archiveEntries: listing.length,
  extracted: {
    files: files.length,
    directories: entries.filter((e) => e.kind === 'dir').length,
    symlinks: entries.filter((e) => e.kind === 'symlink').length,
    special: entries.filter((e) => e.kind === 'special').length,
  },
  gitTree: {
    sha: tree.sha,
    truncated: tree.truncated,
    entries: tree.tree.length,
    blobs: treeBlobs.size,
    directories: treeDirs.length,
    symlinks: treeSymlinks.length,
    gitlinks: treeCommits.length,
    executableBlobs: treeExecutable.length,
  },
  parity: {
    missingFiles: missing,
    extraFiles: extra,
    mismatchedBlobs: mismatched,
    normalizedManifestSha256,
  },
  lfs: {
    gitattributesPresent: files.some((f) => f.path.endsWith('.gitattributes')),
    pointerFiles: lfsPointers.map((f) => f.path),
  },
  licence: {
    path: 'LICENSE',
    bytes: licenseBuf.length,
    gitBlobSha: blobShaByPath.get('LICENSE'),
    sha256: sha256ByPath.get('LICENSE'),
    firstLine: licenseText.split('\n')[0],
    copyrightLine: licenseText.split('\n').find((l) => /copyright/i.test(l)) ?? null,
    permissionGrant: licenseText.includes('Permission is hereby granted, free of charge'),
    noticeRetention: licenseText.includes(
      'The above copyright notice and this permission notice shall be included',
    ),
    warrantyDisclaimer: licenseText.includes('WITHOUT WARRANTY OF ANY KIND'),
    fullText: licenseText,
  },
  manifest: {
    path: 'package.json',
    bytes: statSync(join(srcRoot, 'package.json')).size,
    gitBlobSha: blobShaByPath.get('package.json'),
    sha256: sha256ByPath.get('package.json'),
    name: pkg.name,
    version: pkg.version,
    private: pkg.private ?? false,
    licenseField: pkg.license ?? null,
    engines: pkg.engines ?? null,
    scripts: pkg.scripts,
    dependencies: pkg.dependencies,
    devDependencies: pkg.devDependencies,
  },
  lock: {
    candidates: ['yarn.lock', 'package-lock.json', 'npm-shrinkwrap.json', 'pnpm-lock.yaml'].map(
      (p) => ({
        path: p,
        present: blobShaByPath.has(p),
        bytes: blobShaByPath.has(p) ? files.find((f) => f.path === p).bytes : null,
        gitBlobSha: blobShaByPath.get(p) ?? null,
        sha256: sha256ByPath.get(p) ?? null,
      }),
    ),
  },
  inventory: {
    licenceLikeFiles: files
      .map((f) => f.path)
      .filter((p) => /(^|\/)(LICENSE|LICENCE|COPYING|NOTICE)(\.|$)/i.test(p)),
    committedNodeModules: files.filter((f) => f.path.split('/').includes('node_modules')).length,
    committedBuildOutput: files.filter((f) =>
      ['out', 'dist', 'build', '.next'].includes(f.path.split('/')[0]),
    ).length,
    topLevel: [...new Set(files.map((f) => f.path.split('/')[0]))].sort(),
  },
  files: files
    .map((f) => ({ path: f.path, bytes: f.bytes, gitBlobSha: blobShaByPath.get(f.path) }))
    .sort((a, b) => (a.path < b.path ? -1 : 1)),
};

mkdirSync(EVIDENCE_ROOT, { recursive: true });
writeFileSync(join(EVIDENCE_ROOT, '.reconcile-raw.json'), JSON.stringify(record, null, 2) + '\n');
console.log(
  JSON.stringify(
    {
      archiveRoot,
      files: files.length,
      treeBlobs: treeBlobs.size,
      missing: missing.length,
      extra: extra.length,
      mismatched: mismatched.length,
      normalizedManifestSha256,
      lfs: record.lfs,
      licence: {
        bytes: record.licence.bytes,
        gitBlobSha: record.licence.gitBlobSha,
        sha256: record.licence.sha256,
        firstLine: record.licence.firstLine,
        copyrightLine: record.licence.copyrightLine,
        grants: [
          record.licence.permissionGrant,
          record.licence.noticeRetention,
          record.licence.warrantyDisclaimer,
        ],
      },
      manifest: {
        name: pkg.name,
        version: pkg.version,
        license: pkg.license,
        engines: pkg.engines ?? null,
        scripts: pkg.scripts,
      },
      lock: record.lock.candidates.filter((c) => c.present),
      topLevel: record.inventory.topLevel,
    },
    null,
    2,
  ),
);

