        script.onerror = () => {
            updateShowFallback(true);
        };
        script.addEventListener("load", () => {
            if (adShowing()) {
                _.invoke((window as any)._carbonads, "refresh")
                updateForceUpdate(1);
            }
        });

        document.querySelector(`#${name}`)?.appendChild(script);
