#!/usr/bin/env node
/**
 * Offline closure driver. Reads the committed yarn.lock as text (no resolver,
 * no network) and the installed baseline tree, and reports what the lock
 * actually pins plus what the install actually placed. No network.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const WT = process.cwd();
const SRC = join(
  WT,
  '.versionless/cache/next-killedbygoogle-v3-0-0-source/verify/extracted/killedbygoogle-56809c31592e6ca1edce8af9bfe842fbcdf71f4d',
);
const APP = join(WT, '.versionless/cache/next-killedbygoogle-v3-0-0-baseline/app');
const OUT = join(WT, 'evidence/ingests/next-killedbygoogle-v3-0-0/.closure-raw.json');

const lockText = readFileSync(join(SRC, 'yarn.lock'), 'utf8');
const lines = lockText.split('\n');

const header = lines.slice(0, 5).filter((l) => l.startsWith('#'));
const entries = [];
let current = null;
for (const line of lines) {
  if (line.startsWith('#') || line.trim() === '') continue;
  if (!line.startsWith(' ')) {
    if (current) entries.push(current);
    current = { specifiers: line.replace(/:$/, '').split(', ').map((s) => s.replace(/^"|"$/g, '')) };
  } else if (current) {
    const m = line.trim().match(/^(version|resolved|integrity)\s+(.*)$/);
    if (m) current[m[1]] = m[2].replace(/^"|"$/g, '');
  }
}
if (current) entries.push(current);

const resolvedHosts = {};
let withIntegrity = 0;
const integrityAlgorithms = new Set();
const noIntegrity = [];
for (const e of entries) {
  if (e.resolved) {
    try {
      const h = new URL(e.resolved).hostname;
      resolvedHosts[h] = (resolvedHosts[h] ?? 0) + 1;
    } catch {
      resolvedHosts['<unparsable>'] = (resolvedHosts['<unparsable>'] ?? 0) + 1;
    }
  }
  if (e.integrity) {
    withIntegrity += 1;
    integrityAlgorithms.add(e.integrity.split('-')[0]);
  } else {
    noIntegrity.push(e.specifiers[0]);
  }
}

const nameVersion = new Set(
  entries
    .filter((e) => e.version)
    .map((e) => {
      const spec = e.specifiers[0];
      const at = spec.lastIndexOf('@');
      return `${spec.slice(0, at)}@${e.version}`;
    }),
);

function installedVersion(name) {
  const p = join(APP, 'node_modules', name, 'package.json');
  if (!existsSync(p)) return null;
  return JSON.parse(readFileSync(p, 'utf8')).version;
}

const interesting = [
  'next',
  'react',
  'react-dom',
  'react-select',
  'typescript',
  'webpack',
  '@emotion/react',
  '@emotion/styled',
  '@emotion/core',
  '@svgr/webpack',
  'slugify',
  'date-fns',
  'lodash',
  '@playwright/test',
  'eslint-config-next',
  '@next/swc-darwin-arm64',
];
const installed = Object.fromEntries(interesting.map((n) => [n, installedVersion(n)]));

let placements = 0;
function countPlacements(dir) {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    if (name.startsWith('.')) continue;
    if (name.startsWith('@')) {
      for (const scoped of readdirSync(join(dir, name))) {
        placements += 1;
        countPlacements(join(dir, name, scoped, 'node_modules'));
      }
    } else {
      placements += 1;
      countPlacements(join(dir, name, 'node_modules'));
    }
  }
}
countPlacements(join(APP, 'node_modules'));

const record = {
  lock: {
    path: 'yarn.lock',
    bytes: Buffer.byteLength(lockText),
    sha256: createHash('sha256').update(lockText).digest('hex'),
    header,
    entryBlocks: entries.length,
    specifiers: entries.reduce((n, e) => n + e.specifiers.length, 0),
    distinctNameVersionPairs: nameVersion.size,
    everyEntryHasResolvedUrl: entries.every((e) => Boolean(e.resolved)),
    entriesWithIntegrity: withIntegrity,
    entriesWithoutIntegrity: noIntegrity,
    integrityAlgorithms: [...integrityAlgorithms].sort(),
    resolvedHosts,
  },
  installed,
  placements,
};
writeFileSync(OUT, JSON.stringify(record, null, 2) + '\n');
console.log(JSON.stringify(record, null, 2));

