      resolvedHosts[h] = (resolvedHosts[h] ?? 0) + 1;
    } catch {
      resolvedHosts['<unparsable>'] = (resolvedHosts['<unparsable>'] ?? 0) + 1;
    }
  }
  if (e.integrity) {
    withIntegrity += 1;
    integrityAlgorithms.add(e.integrity.split('-')[0]);
  } else {
    noIntegrity.push(e.specifiers[0]);
  }
}

const nameVersion = new Set(
  entries
    .filter((e) => e.version)
    .map((e) => {
      const spec = e.specifiers[0];
      const at = spec.lastIndexOf('@');
      return `${spec.slice(0, at)}@${e.version}`;
    }),
);

function installedVersion(name) {
  const p = join(APP, 'node_modules', name, 'package.json');
  if (!existsSync(p)) return null;
  return JSON.parse(readFileSync(p, 'utf8')).version;
}

const interesting = [
  'next',
  'react',
  'react-dom',
  'react-select',
  'typescript',
  'webpack',
  '@emotion/react',
  '@emotion/styled',
  '@emotion/core',
  '@svgr/webpack',
  'slugify',
  'date-fns',
  'lodash',
  '@playwright/test',
  'eslint-config-next',
  '@next/swc-darwin-arm64',
];
const installed = Object.fromEntries(interesting.map((n) => [n, installedVersion(n)]));

let placements = 0;
function countPlacements(dir) {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    if (name.startsWith('.')) continue;
    if (name.startsWith('@')) {
      for (const scoped of readdirSync(join(dir, name))) {
        placements += 1;
        countPlacements(join(dir, name, scoped, 'node_modules'));
      }
    } else {
      placements += 1;
      countPlacements(join(dir, name, 'node_modules'));
    }
  }
}
countPlacements(join(APP, 'node_modules'));

const record = {
  lock: {
    path: 'yarn.lock',
    bytes: Buffer.byteLength(lockText),
    sha256: createHash('sha256').update(lockText).digest('hex'),
    header,
    entryBlocks: entries.length,
    specifiers: entries.reduce((n, e) => n + e.specifiers.length, 0),
    distinctNameVersionPairs: nameVersion.size,
    everyEntryHasResolvedUrl: entries.every((e) => Boolean(e.resolved)),
    entriesWithIntegrity: withIntegrity,
    entriesWithoutIntegrity: noIntegrity,
    integrityAlgorithms: [...integrityAlgorithms].sort(),
    resolvedHosts,
  },
  installed,
  placements,
};
writeFileSync(OUT, JSON.stringify(record, null, 2) + '\n');
console.log(JSON.stringify(record, null, 2));

