node -e "
const fs=require('fs');
const dir='./evidence/ingests/next-killedbygoogle-v3-0-0/';
let bad=0;
for(const f of fs.readdirSync(dir)){
  if(!f.endsWith('.json'))continue;
  try{JSON.parse(fs.readFileSync(dir+f,'utf8'));console.log('OK',f);}catch(e){bad++;console.log('BAD',f,e.message);}
}
try{JSON.parse(fs.readFileSync('./fixtures/next-killedbygoogle-v3-0-0/fixture.json','utf8'));console.log('OK fixture.json');}catch(e){bad++;console.log('BAD fixture.json',e.message);}
for(const f of ['probe-ledger.ndjson','transcript.ndjson']){
  const lines=fs.readFileSync(dir+f,'utf8').split('\n').filter(Boolean);
  lines.forEach((l,i)=>{try{JSON.parse(l)}catch(e){bad++;console.log('BAD',f,'line',i+1,e.message)}});
  console.log('OK',f,lines.length,'lines');
}
console.log(bad?'FAILURES '+bad:'ALL VALID');
"
